<?php
session_start();
// Security Check
if (!isset($_SESSION['user_id']) || !in_array($_SESSION['role'], ['admin', 'branch_staff'])) {
    header("Location: login.php");
    exit();
}

require_once 'config.php';

$conn = new mysqli(DB_HOST, DB_USER, DB_PASS, DB_NAME);
if ($conn->connect_error) { die("Connection failed: " . $conn->connect_error); }

$registration_id = $_GET['id'] ?? null;
$registration_data = null;
$error_message = '';

// Determine if the current user is an Admin
$is_admin = ($_SESSION['role'] === 'admin');

// Fetch available license categories for the dropdown
$license_categories = [];
$cat_result = $conn->query("SELECT category_name, base_price FROM license_categories ORDER BY category_name");
if ($cat_result) { while ($row = $cat_result->fetch_assoc()) { $license_categories[] = $row; } }

if (!$registration_id) {
    $error_message = "No registration ID provided.";
} else {
    // Adjusted query to handle branch restriction for staff
    $query = "SELECT r.*, u_created.username as created_by_username, u_edited.username as last_edited_by_username
              FROM registrations r
              LEFT JOIN users u_created ON r.created_by_user_id = u_created.id
              LEFT JOIN users u_edited ON r.last_edited_by_user_id = u_edited.id
              WHERE r.id = ?";
    $params = [$registration_id];
    $param_types = "i";

    if (!$is_admin) { // Apply branch filter only if user is NOT admin
        $query .= " AND r.branch = ?";
        $params[] = $_SESSION['branch_name'];
        $param_types .= "s";
    }

    $stmt = $conn->prepare($query);
    if ($stmt === false) {
        $error_message = "Database query failed to prepare: " . $conn->error;
    } else {
        $stmt->bind_param($param_types, ...$params);
        $stmt->execute();
        $result = $stmt->get_result();
        $registration_data = $result->fetch_assoc(); // $registration_data will be null if no record found
        $stmt->close();

        if (!$registration_data) {
            $error_message = "Student with the specified ID was not found or does not belong to your branch.";
        }
    }
}
$conn->close();

// Determine base URL for QR code (adjust if needed)
$protocol = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off' || $_SERVER['SERVER_PORT'] == 443) ? "https://" : "http://";
$host = $_SERVER['HTTP_HOST'];
$script_dir = dirname($_SERVER['PHP_SELF']);
$base_url = rtrim($protocol . $host . $script_dir, '/');

// Helper function to check if ANY field should be readonly for non-admins
function isReadOnlyForUser($fieldName, $fieldValue, $isAdmin) {
    $oneTimeEditFields = [
        'full_name', 'name_with_initials', 'id_number', 'phone_number', 'address', 'dob', 'age', 'sex', 'customer_email',
        'appointment_date', 'license_category', 'exam_date_branch', 'book_release_date', 'appointment_gov_date', 'appointment_change_date', 'appointment_change_date_2',
        'medical_b_date', 'medical_fee', 'medical_paid_date', 'remedical_b_date_2', 'remedical_ref_no_2', 'remedical_fee_2', 'remedical_b_date_3', 'remedical_ref_no_3', 'remedical_fee_3', 'medical_done',
        'invoice_no', 'invoice_date', 'total_amount', 'advance_paid', 'full_payment_paid', 'repayment_date', 'repayment_amount', 'repayment_date_3', 'repayment_amount_3', 'repayment_date_4', 'repayment_amount_4', 'payment_done',
        'required_training_days',
        'trial_1_date', 'trial_1_result', 'trial_1_notes', 'trial_2_date', 'trial_2_result', 'trial_2_notes',
        'temp_license_issue_date', 'permanent_license_status', 'permanent_license_issued_date'
    ];
    if ($isAdmin) { return false; }
    if (in_array($fieldName, $oneTimeEditFields)) {
        if (in_array($fieldName, ['medical_done', 'full_payment_paid', 'payment_done'])) { return ($fieldValue == 1); }
        elseif (in_array($fieldName, ['age', 'medical_fee', 'remedical_fee_2', 'remedical_fee_3', 'total_amount', 'advance_paid', 'repayment_amount', 'repayment_amount_3', 'repayment_amount_4', 'required_training_days'])) { return (!is_null($fieldValue) && is_numeric($fieldValue) && $fieldValue > 0); }
        elseif (in_array($fieldName, ['sex', 'trial_1_result', 'trial_2_result', 'permanent_license_status'])) { return (!is_null($fieldValue) && $fieldValue !== '' && $fieldValue !== 'Pending' && $fieldValue !== 'Not Applicable'); }
        else { return (!is_null($fieldValue) && $fieldValue !== ''); }
    }
    return false;
}
function readOnlyAttr($fieldName, $fieldValue, $isAdmin) { return isReadOnlyForUser($fieldName, $fieldValue, $isAdmin) ? 'readonly' : ''; }
function disabledAttr($fieldName, $fieldValue, $isAdmin) { return isReadOnlyForUser($fieldName, $fieldValue, $isAdmin) ? 'disabled' : ''; }

