    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script>
    <script>
        document.addEventListener('DOMContentLoaded', function() {
            // *** MOVED JS variables that DEPEND on $registration_data INSIDE the check ***
            const registrationDataJSON = <?php echo json_encode($registration_data); ?>; // Get data once

            // Only run scripts that need registrationData if it exists
            if (registrationDataJSON) {
                const isAdmin = <?php echo json_encode($is_admin); ?>;
                const registrationData = registrationDataJSON; // Use the JS variable

                // Payment Calculation Logic (existing code - now safe)
                const totalAmount = document.getElementById('total_amount'); const advancePaid = document.getElementById('advance_paid'); const balance1 = document.getElementById('balance_1'); const fullPaymentPaid = document.getElementById('full_payment_paid'); const repay2 = document.getElementById('repayment_amount_2'); const reBalance2 = document.getElementById('re_balance_2'); const repay3 = document.getElementById('repayment_amount_3'); const reBalance3 = document.getElementById('re_balance_3'); const repay4 = document.getElementById('repayment_amount_4'); const reBalance4 = document.getElementById('re_balance_4'); const paymentDone = document.getElementById('payment_done'); const inputsToWatch = [totalAmount, advancePaid, repay2, repay3, repay4];
                window.calculateAllBalances = function() { const total = parseFloat(totalAmount?.value) || 0; const advance = parseFloat(advancePaid?.value) || 0; const r2 = parseFloat(repay2?.value) || 0; const r3 = parseFloat(repay3?.value) || 0; const r4 = parseFloat(repay4?.value) || 0; const bal1 = total - advance; const bal2 = bal1 - r2; const bal3 = bal2 - r3; const bal4 = bal3 - r4; if(balance1) balance1.value = bal1.toFixed(2); if(reBalance2) reBalance2.value = bal2.toFixed(2); if(reBalance3) reBalance3.value = bal3.toFixed(2); if(reBalance4) reBalance4.value = bal4.toFixed(2); if(fullPaymentPaid) fullPaymentPaid.checked = (bal1 <= 0 && total > 0); if(paymentDone) paymentDone.checked = (bal4 <= 0 && total > 0); }
                inputsToWatch.forEach(input => { if (input && !input.readOnly) { input.addEventListener('input', calculateAllBalances); } }); calculateAllBalances();

                // License Category Price Update Logic (existing code - now safe)
                window.updateLicensePrice = function() { const select = document.getElementById('license_category'); const selectedOption = select.options[select.selectedIndex]; const price = selectedOption.getAttribute('data-price'); const totalAmountInput = document.getElementById('total_amount'); if (price && totalAmountInput && !totalAmountInput.readOnly) { totalAmountInput.value = parseFloat(price).toFixed(2); calculateAllBalances(); } }

                // QR Code Logic (existing code - now safe)
                const studentIdNumber = registrationData?.id_number || ''; const siteBaseUrl = "<?php echo $base_url; ?>"; const studentQrModal = document.getElementById('studentQrModal');
                if(studentQrModal) { studentQrModal.addEventListener('shown.bs.modal', function () { const qrContainer = document.getElementById('studentQrcodeContainer'); qrContainer.innerHTML = ''; if(studentIdNumber) { const qrLink = `${siteBaseUrl}/find_student.php?id_number=${encodeURIComponent(studentIdNumber)}`; try { new QRCode(qrContainer, { text: qrLink, width: 200, height: 200, colorDark : "#000000", colorLight : "#ffffff", correctLevel : QRCode.CorrectLevel.H }); } catch (e) { console.error("QR Code generation failed:", e); qrContainer.innerHTML = "<p class='text-danger'>Error generating QR code.</p>"; } } else { qrContainer.innerHTML = "<p class='text-warning'>Student ID number not available.</p>"; } }); }

                // CHANGE PICTURE MODAL LOGIC (existing code - now safe)
                const changePicModalElement = document.getElementById('changePictureModal'); if (changePicModalElement) { const videoModal = document.getElementById('video-feed-modal'); const canvasModal = document.getElementById('photo-canvas-modal'); const photoPreviewModal = document.getElementById('photo-preview-modal'); const startCameraButtonModal = document.getElementById('start-camera-btn-modal'); const captureButtonModal = document.getElementById('capture-btn-modal'); const retakeButtonModal = document.getElementById('retake-btn-modal'); const hiddenInputModal = document.getElementById('profile_picture_data_modal'); const cameraPlaceholderModal = document.getElementById('camera-placeholder-modal'); const fileInputModal = document.getElementById('profile_picture_file_modal'); let streamModal = null; changePicModalElement.addEventListener('show.bs.modal', () => { stopCameraModal(); clearFileInputModal(); photoPreviewModal.style.display = 'none'; photoPreviewModal.removeAttribute('src'); hiddenInputModal.value = ''; retakeButtonModal.style.display = 'none'; cameraPlaceholderModal.style.display = 'block'; cameraPlaceholderModal.textContent = 'Camera feed or selected image will appear here'; captureButtonModal.disabled = true; startCameraButtonModal.disabled = false; fileInputModal.disabled = false; }); changePicModalElement.addEventListener('hidden.bs.modal', () => { stopCameraModal(); }); startCameraButtonModal.addEventListener('click', async () => { if (streamModal && videoModal.style.display === 'block') { stopCameraModal(); } else { clearFileInputModal(); if (streamModal) { streamModal.getTracks().forEach(track => track.stop()); } try { streamModal = await navigator.mediaDevices.getUserMedia({ video: true, audio: false }); videoModal.srcObject = streamModal; videoModal.style.display = 'block'; photoPreviewModal.style.display = 'none'; retakeButtonModal.style.display = 'none'; captureButtonModal.disabled = false; startCameraButtonModal.textContent = 'Stop Camera'; startCameraButtonModal.classList.remove('btn-secondary'); startCameraButtonModal.classList.add('btn-danger'); cameraPlaceholderModal.style.display = 'none'; hiddenInputModal.value = ''; } catch (err) { console.error("Modal Camera Error: ", err); cameraPlaceholderModal.textContent = 'Error: Could not access camera.'; cameraPlaceholderModal.style.display = 'block'; alert('Could not access the camera. Ensure permissions are granted.'); } } }); captureButtonModal.addEventListener('click', () => { if (!streamModal || videoModal.style.display === 'none') return; canvasModal.width = videoModal.videoWidth; canvasModal.height = videoModal.videoHeight; const context = canvasModal.getContext('2d'); context.drawImage(videoModal, 0, 0, canvasModal.width, canvasModal.height); const dataUrl = canvasModal.toDataURL('image/jpeg', 0.8); photoPreviewModal.src = dataUrl; photoPreviewModal.style.display = 'block'; hiddenInputModal.value = dataUrl.split(',')[1]; stopCameraModal(); captureButtonModal.disabled = true; retakeButtonModal.style.display = 'block'; fileInputModal.disabled = true; }); retakeButtonModal.addEventListener('click', () => { stopCameraModal(); clearFileInputModal(); photoPreviewModal.style.display = 'none'; photoPreviewModal.removeAttribute('src'); hiddenInputModal.value = ''; retakeButtonModal.style.display = 'none'; cameraPlaceholderModal.style.display = 'block'; cameraPlaceholderModal.textContent = 'Camera feed or selected image will appear here'; captureButtonModal.disabled = true; fileInputModal.disabled = false; startCameraButtonModal.disabled = false; }); function stopCameraModal() { if (streamModal) { streamModal.getTracks().forEach(track => track.stop()); streamModal = null; } if(videoModal) videoModal.style.display = 'none'; if(videoModal) videoModal.srcObject = null; if(captureButtonModal) captureButtonModal.disabled = true; if(startCameraButtonModal) { startCameraButtonModal.textContent = 'Start/Stop Camera'; startCameraButtonModal.classList.remove('btn-danger'); startCameraButtonModal.classList.add('btn-secondary'); } if (photoPreviewModal && photoPreviewModal.style.display === 'none') { if(cameraPlaceholderModal) cameraPlaceholderModal.style.display = 'block'; if(cameraPlaceholderModal) cameraPlaceholderModal.textContent = 'Camera feed or selected image will appear here'; } } fileInputModal.addEventListener('change', (event) => { const file = event.target.files[0]; if (file) { stopCameraModal(); startCameraButtonModal.disabled = true; const reader = new FileReader(); reader.onload = (e) => { photoPreviewModal.src = e.target.result; photoPreviewModal.style.display = 'block'; hiddenInputModal.value = ''; cameraPlaceholderModal.style.display = 'none'; retakeButtonModal.style.display = 'block'; captureButtonModal.disabled = true; } ;async (params) => {
                    reader.readAsDataURL(file)
                }; } }); function clearFileInputModal() { if (fileInputModal) fileInputModal.value = null; if (fileInputModal) fileInputModal.disabled = false; } }

                // Group Session History Logic (existing code - now safe)
                const groupSessionsTabButton = document.querySelector('button[data-bs-target="#group-sessions-tab-pane"]'); if (groupSessionsTabButton) { groupSessionsTabButton.addEventListener('shown.bs.tab', loadGroupSessionHistory, { once: true }); }
                async function loadGroupSessionHistory() { const historyDiv = document.getElementById('session-history-content'); historyDiv.innerHTML = '<div class="text-center p-3"><span class="spinner-border spinner-border-sm"></span> Loading...</div>'; const studentId = registrationData?.id; const requiredDaysInput = document.querySelector('input[name="required_training_days"]'); const requiredDays = requiredDaysInput ? parseInt(requiredDaysInput.value, 10) || 0 : 0; if (!studentId) { historyDiv.innerHTML = '<div class="alert alert-warning">Student ID not found.</div>'; return; } try { const response = await fetch(`process_group_sessions.php?action=fetch_student_history&student_id=${studentId}`); if (!response.ok) throw new Error(`Network error (${response.status})`); const data = await response.json(); if (data.success) { const attendedDays = data.history.filter(rec => rec.status === 'Present').length; const progress = requiredDays > 0 ? Math.min((attendedDays / requiredDays) * 100, 100) : 0; let historyHtml = ''; if (data.history.length > 0) { let table = '<div class="table-responsive"><table class="table table-sm table-striped table-hover"><thead><tr><th>Session</th><th>Date</th><th>Status</th><th>Marked By</th><th>Time</th></tr></thead><tbody>'; data.history.forEach(rec => { let statusBadge = `<span class="badge bg-secondary">${htmlspecialchars(rec.status)}</span>`; if (rec.status === 'Present') statusBadge = `<span class="badge bg-success">${htmlspecialchars(rec.status)}</span>`; if (rec.status === 'Absent') statusBadge = `<span class="badge bg-danger">${htmlspecialchars(rec.status)}</span>`; let markedAt = rec.marked_at ? new Date(rec.marked_at).toLocaleString() : 'N/A'; table += `<tr><td>${htmlspecialchars(rec.session_title)}</td><td>${htmlspecialchars(rec.session_date)}</td><td>${statusBadge}</td><td>${htmlspecialchars(rec.marked_by || 'N/A')}</td><td>${markedAt}</td></tr>`; }); table += '</tbody></table></div>'; historyHtml = table; } else { historyHtml = '<div class="alert alert-info">No group session history.</div>'; } historyDiv.innerHTML = `<h5>Attendance Progress</h5><p><strong>${attendedDays}</strong> / <strong>${requiredDays}</strong> days completed.</p><div class="progress mb-4" style="height: 25px;"><div class="progress-bar bg-success progress-bar-striped progress-bar-animated" role="progressbar" style="width: ${progress}%;" aria-valuenow="${attendedDays}" aria-valuemin="0" aria-valuemax="${requiredDays}">${Math.round(progress)}%</div></div>${historyHtml}`; } else { throw new Error(data.message || 'Failed to fetch history.'); } } catch (error) { console.error("Error loading group session history:", error); historyDiv.innerHTML = `<div class="alert alert-danger">Error: ${htmlspecialchars(error.message)}</div>`; } }
                function htmlspecialchars(str) { if (typeof str !== 'string') return str === null || str === undefined ? '' : String(str); const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }; return str.replace(/[&<>"']/g, function(m) { return map[m]; }); }

            } // *** End of if (registrationDataJSON) check ***

        }); // End DOMContentLoaded
    </script>

</body>
</html>